import {AudioEngine} from './engine.js';
import {createVideoMixer} from './video.js';
import {videoFileIdentity} from './video-file-identity.js';
import {snapshotVideoState,restoreVideoState} from './video-state.js';
const $=s=>document.querySelector(s),raf=()=>new Promise(resolve=>requestAnimationFrame(resolve));
const assert=(condition,message)=>{if(!condition)throw Error(message);};
const W=640,H=360,urls=new Set();
function publish(blob,name){const url=URL.createObjectURL(blob);urls.add(url);const link=document.createElement('a');link.href=url;link.download=name;link.textContent=`Download ${name} (${blob.size} bytes)`;$('#downloads').append(link);return{name,bytes:blob.size,type:blob.type};}
function clearDownloads(){for(const url of urls)URL.revokeObjectURL(url);urls.clear();$('#downloads').replaceChildren();}
window.addEventListener('pagehide',clearDownloads);
function bounded(promise,label,ms=20000){let timer;return Promise.race([promise,new Promise((_,reject)=>{timer=setTimeout(()=>reject(Error(label+' timed out')),ms);})]).finally(()=>clearTimeout(timer));}
const near=(actual,expected,tolerance=2)=>actual.every((value,index)=>Math.abs(value-expected[index])<=tolerance);
const fx=(name,value=1,params={})=>({name,on:true,value,params});
const negative=()=>[fx('Negative'),{name:'Gamma',on:false,value:.4,params:{behavior:'Manual Meaning',shadowPower:3}}];
const gamma=power=>[fx('Gamma',1,{behavior:'Manual Meaning',shadowPower:power})];
const rgba=(canvas,x=.5,y=.5)=>{const c=canvas.getContext('2d');return [...c.getImageData(Math.floor(x*canvas.width),Math.floor(y*canvas.height),1,1).data];};
const inverse=p=>p.map((v,i)=>i===3?v:255-v),dark=(p,power)=>p.map((v,i)=>i===3?v:Math.round(255*(v/255)**power));
async function encodedFixture(color,kind){
 const canvas=document.createElement('canvas');canvas.width=160;canvas.height=90;$('#fixture-stage').append(canvas);const ctx=canvas.getContext('2d'),paint=()=>{ctx.fillStyle=`rgb(${color})`;ctx.fillRect(0,0,160,90);ctx.fillStyle=kind==='red'?'#28b428':'#b428b4';ctx.fillRect(kind==='red'?120:8,kind==='red'?8:60,24,16);};paint();
 const stream=canvas.captureStream(12),mime=['video/webm;codecs=vp8','video/webm;codecs=vp9','video/webm','video/mp4'].find(type=>MediaRecorder.isTypeSupported(type)),chunks=[];assert(mime,'No actual canvas-video encoder');
 const recorder=new MediaRecorder(stream,{mimeType:mime}),done=new Promise((resolve,reject)=>{recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};recorder.onerror=e=>reject(e.error||Error('Fixture encoder failed'));recorder.onstop=()=>resolve(new Blob(chunks,{type:recorder.mimeType}));});
 let frames=0;const started=performance.now();try{recorder.start(100);while(performance.now()-started<750||frames<8){paint();stream.getVideoTracks()[0].requestFrame?.();frames++;await raf();}recorder.stop();const blob=await bounded(done,'Generated fixture encoding');assert(blob.size>100,'Encoded fixture was empty');return{file:new File([blob],'open-play-shared-name.'+(mime.includes('mp4')?'mp4':'webm'),{type:blob.type}),frames,elapsedMs:performance.now()-started,mime:recorder.mimeType};}finally{if(recorder.state!=='inactive')recorder.stop();stream.getTracks().forEach(track=>track.stop());canvas.remove();}
}
function stateFor(video={}){return{settings:{},decks:[0,1].map(index=>({index,track:null,position:0,rate:1,playing:false})),video:{width:W,height:H,linked:false,crossLinked:false,cross:-1,channelOpacity:[1,1],channelOpacityLinked:[false,false],fx:{left:[],right:[],master:[]},overlays:{left:[],right:[],master:[]},...video}};}
export async function runVideoFXPresetChecks(){
 clearDownloads();const checks=[],notifications=[],report={startedAt:new Date().toISOString(),checks,notifications,scope:'Actual generated MediaRecorder video Files, presented source decode, real module Worker streaming SHA-256, actual mixer/metadata/GPU/JSON restoration and real AudioEngine RMS. Synthetic originals only. Does not prove Serato identity/storage/curves, arbitrary codecs or native/hardware compatibility.'};
 const engine=new AudioEngine();engine.init();engine.analyser.disconnect();const resumed=engine.ctx.resume();let mixer,state,A,B,renamed,keyA,keyB,rawA,rawB,osc,gain,exported;
 function create(video){state=stateFor(video);mixer=createVideoMixer({state,engine,notify:message=>notifications.push(message)});mixer.bind($('#output'));return mixer;}
 function tick(){mixer.tick(true);const d=mixer.diagnostics();assert(!d.error,'Actual mixer pipeline error: '+d.error);return rgba($('#output'));}
 async function test(name,run){$('#status').textContent=`Running ${checks.length+1}: ${name}`;const evidence={};try{const result=await run(evidence);checks.push({name,passed:true,evidence:result??evidence});}catch(error){checks.push({name,passed:false,evidence,error:error.stack||error.message});}$('#results').textContent=JSON.stringify(report,null,2);await raf();}
 async function waitAudio(seconds){const until=engine.ctx.currentTime+seconds,end=performance.now()+10000;while(engine.ctx.currentTime<until){assert(performance.now()<end,'Audio clock did not reach fixed observation aperture');await raf();}}
 try{
  await test('Actual original red/blue containers encode different bytes despite the same filename; renamed copy hashes identically',async evidence=>{
   await resumed;await engine.resume();assert(typeof Worker==='function'&&typeof MediaRecorder==='function','Real Worker and MediaRecorder are required');const a=await encodedFixture([180,64,48],'red'),b=await encodedFixture([48,72,180],'blue');A=a.file;B=b.file;renamed=new File([A],'open-play-fx-renamed-red.webm',{type:A.type});
   [keyA,keyB]=await Promise.all([videoFileIdentity(A),videoFileIdentity(B)]);const renamedKey=await videoFileIdentity(renamed);assert(A.name===B.name&&keyA!==keyB&&renamedKey===keyA,'Real content identity confused same name/different content or renamed same bytes');
   report.fixtures={red:publish(A,'open-play-fx-red.webm'),blue:publish(B,'open-play-fx-blue.webm'),renamed:publish(renamed,renamed.name)};osc=engine.ctx.createOscillator();gain=engine.ctx.createGain();osc.frequency.value=440;gain.gain.value=.15;osc.connect(gain);gain.connect(engine.nodes[0].input);osc.start();create();Object.assign(evidence,{sameSourceFilename:A.name,keyA,keyB,renamedKey,encodedFrames:[a.frames,b.frames],elapsedMs:[a.elapsedMs,b.elapsedMs],mime:[a.mime,b.mime],bytes:[A.size,B.size],speakerRoute:'Disconnected before local440Hz source was connected'});
  });
  await test('Red File decodes a real presented frame and saves two channel slots with actual Negative pixels',async evidence=>{
   assert(mixer&&A,'Fixture setup failed');await bounded(mixer.load(0,A),'Actual red load');rawA=tick();const decoded=mixer.diagnostics().inputs[0];assert(decoded.firstFrame?.width===160&&decoded.firstFrame?.height===90&&decoded.firstFrame.presentedFrames>=1,'No actual source frame proof');assert(rawA[0]>140&&rawA[1]<100&&rawA[2]<90&&rawA[3]===255,'Actual red content missing: '+rawA);
   state.video.fx.left=negative();const processed=tick(),record=await bounded(mixer.saveVideoFX(0),'Actual red save');assert(record.key===keyA&&record.fx.length===2&&record.fx[0].name==='Negative'&&!record.fx[1].on,'Wrong identity/slot snapshot');assert(near(processed,inverse(rawA)),'Negative output does not match actual decoded source: '+JSON.stringify({rawA,processed}));Object.assign(evidence,{raw:rawA,processed,expected:inverse(rawA),decoded,record,status:mixer.diagnostics().savedFX.channels[0]});
  });
  await test('Same-name blue File has no red preset match; automatic and explicit no-match keep current settings',async evidence=>{
   assert(mixer&&B,'Fixture setup failed');await bounded(mixer.load(0,B),'Actual blue no-match load');const status=mixer.diagnostics().savedFX.channels[0],retained=tick();assert(status.identity===keyB&&/No saved FX/.test(status.status)&&state.video.fx.left[0].name==='Negative','Filename/global preset leaked or current FX changed');let error;try{await mixer.recallVideoFX(0);}catch(e){error=e.message;}assert(/No saved FX/.test(error||''),'Explicit no-match did not report absence');assert(near(retained,tick()),'No-match recall changed pixels');state.video.fx.left=[];rawB=tick();assert(rawB[2]>140&&rawB[0]<100&&rawB[1]<110&&rawB[3]===255,'Blue fixture decoded wrong: '+rawB);assert(near(retained,inverse(rawB)),'No-match did not retain current Negative behavior');Object.assign(evidence,{raw:rawB,retained,expected:inverse(rawB),status,explicitError:error});
  });
  await test('Blue File independently saves manual Gamma power2 and produces measured darkened source pixels',async evidence=>{
   state.video.fx.left=gamma(2);const processed=tick(),record=await bounded(mixer.saveVideoFX(0),'Actual blue save');assert(record.key===keyB&&record.fx[0].params.shadowPower===2,'Blue save lost independent curve');assert(near(processed,dark(rawB,2)),'Gamma did not darken actual source by its declared independent curve');assert(mixer.exportVideoFX().records.length===2,'Same filename collapsed different content identities');Object.assign(evidence,{raw:rawB,processed,expected:dark(rawB,2),record});
  });
  await test('Reloading real red bytes automatically recalls Negative before the new clip commits',async()=>{
   await bounded(mixer.load(0,new File([A],A.name,{type:A.type})),'Actual red reload');const p=tick(),d=mixer.diagnostics();assert(d.savedFX.channels[0].identity===keyA&&state.video.fx.left[0].name==='Negative'&&near(p,inverse(rawA)),'Red content did not recall its own settings');return{pixel:p,expected:inverse(rawA),savedFX:d.savedFX};
  });
  await test('Reloading real blue bytes independently recalls Gamma power2',async()=>{
   await bounded(mixer.load(0,new File([B],B.name,{type:B.type})),'Actual blue reload');const p=tick();assert(state.video.fx.left[0].name==='Gamma'&&state.video.fx.left[0].params.shadowPower===2&&near(p,dark(rawB,2)),'Blue content inherited red settings');return{pixel:p,expected:dark(rawB,2),savedFX:mixer.diagnostics().savedFX};
  });
  await test('Renamed identical red bytes recall the same saved Negative record',async()=>{
   await bounded(mixer.load(0,renamed),'Actual renamed red load');const p=tick(),d=mixer.diagnostics();assert(d.inputs[0].name===renamed.name&&d.savedFX.channels[0].identity===keyA&&state.video.fx.left[0].name==='Negative'&&near(p,inverse(rawA)),'Rename changed content ownership');return{pixel:p,name:d.inputs[0].name,identity:d.savedFX.channels[0].identity};
  });
  await test('Explicit red recall changes only its channel while decoded right and configured master remain intact',async()=>{
   await bounded(mixer.load(1,B),'Actual right blue load');state.video.fx.master=gamma(1);state.video.fx.left=[];tick();const beforeRight=rgba($('#video-preview-1')),before=JSON.stringify({right:state.video.fx.right,master:state.video.fx.master,transition:state.video.transition,overlays:state.video.overlays});
   const recalled=await mixer.recallVideoFX(0),p=tick(),afterRight=rgba($('#video-preview-1'));assert(recalled.key===keyA&&near(p,inverse(rawA)),'Explicit recall did not restore processed red');assert(near(beforeRight,afterRight,0)&&before===JSON.stringify({right:state.video.fx.right,master:state.video.fx.master,transition:state.video.transition,overlays:state.video.overlays}),'Target recall changed other channel/master/transition/overlays');return{pixel:p,rightBefore:beforeRight,rightAfter:afterRight,master:state.video.fx.master};
  });
  await test('Identical red content loaded on the opposite channel recalls its record without changing left/master',async()=>{
   state.video.fx.left=gamma(3);state.video.cross=1;tick();const leftBefore=rgba($('#video-preview-0')),masterBefore=JSON.stringify(state.video.fx.master);await bounded(mixer.load(1,renamed),'Actual right same-content load');const p=tick(),leftAfter=rgba($('#video-preview-0'));assert(state.video.fx.right[0].name==='Negative'&&near(p,inverse(rawA)),'Shared content did not recall onto the destination channel');assert(near(leftBefore,leftAfter,0)&&masterBefore===JSON.stringify(state.video.fx.master),'Cross-channel recall changed left/master');return{pixel:p,leftBefore,leftAfter,savedFX:mixer.diagnostics().savedFX};
  });
  await test('Actual export and metadata JSON contain two scalar file presets without media/runtime resources',()=>{
   exported=mixer.exportVideoFX();const metadata=snapshotVideoState(state.video),json=JSON.stringify(metadata),round=JSON.parse(json);assert(exported.format==='open-play-video-fx-1'&&exported.records.length===2&&round.savedVideoFX.length===2,'Export/metadata lost per-file records');assert(!/(?:blob:|data:|file:\/\/|holdFrame|captureTime|firstFrame|videoWidth)/.test(json),'Runtime/media data leaked into JSON');report.presetExport=publish(new Blob([JSON.stringify(exported,null,2)],{type:'application/json'}),'open-play-video-fx-presets.json');report.metadataExport=publish(new Blob([JSON.stringify(metadata,null,2)],{type:'application/json'}),'open-play-video-fx-metadata.json');return{format:exported.format,keys:exported.records.map(r=>r.key),records:exported.records,metadataBytes:new Blob([json]).size};
  });
  await test('Restored JSON creates no media resources; explicit original-file reimport recalls actual saved pixels',async()=>{
   const metadata=JSON.parse(JSON.stringify(snapshotVideoState(state.video)));await mixer.dispose();create(restoreVideoState(metadata));assert(mixer.diagnostics().inputs.every(input=>input===null),'JSON restoration resurrected local media');state.video.cross=-1;await bounded(mixer.load(0,new File([A],'restored-red.webm',{type:A.type})),'Actual restored reimport');const p=tick();assert(near(p,inverse(rawA))&&state.video.fx.left[0].name==='Negative','Restored per-file record did not recall after real reimport');return{beforeReimportMedia:'none',afterPixel:p,identity:mixer.diagnostics().savedFX.channels[0].identity,records:mixer.exportVideoFX().records.length};
  });
  await test('Invalid top-level import is atomic; valid mixed import reports drops and replaces only the named identity',()=>{
   const before=JSON.stringify(mixer.exportVideoFX()),beforeFX=JSON.stringify(state.video.fx);let error;try{mixer.importVideoFX({records:[]});}catch(e){error=e.message;}assert(error&&JSON.stringify(mixer.exportVideoFX())===before,'Invalid top-level import changed records');const b={...exported.records.find(r=>r.key===keyB),fx:gamma(3)},counts=mixer.importVideoFX([b,{...b,version:99}]);assert(counts.accepted===1&&counts.dropped===1&&counts.replaced===1&&counts.size===2,'Mixed import counts incorrect');assert(JSON.stringify(state.video.fx)===beforeFX,'Import silently applied settings to loaded channel');return{invalidError:error,counts,unchangedCurrentFX:true};
  });
  await test('Imported blue record recalls its new power3 through real decode and GPU pixels',async()=>{
   await bounded(mixer.load(0,B),'Actual imported blue reload');const p=tick();assert(state.video.fx.left[0].params.shadowPower===3&&near(p,dark(rawB,3)),'Imported metadata did not reach actual blue Gamma pixels');return{pixel:p,expected:dark(rawB,3),identity:mixer.diagnostics().savedFX.channels[0].identity};
  });
  await test('Saving and recalling per-file Video FX leave held actual AudioEngine master RMS unchanged',async()=>{
   engine.videoAnalysis(4);await waitAudio(4*2048/engine.ctx.sampleRate);const windows=[];for(const action of ['baseline','save','recall']){if(action==='save')await mixer.saveVideoFX(0);if(action==='recall'){state.video.fx.left=[];await mixer.recallVideoFX(0);}const samples=[];for(let i=0;i<6;i++){await waitAudio(2048/engine.ctx.sampleRate);tick();samples.push({time:engine.ctx.currentTime,level:engine.videoAnalysis(4).level});}windows.push({action,samples,mean:samples.reduce((sum,row)=>sum+row.level,0)/samples.length});}const levels=windows.map(w=>w.mean);assert(levels[0]>.001&&Math.max(...levels)-Math.min(...levels)<.0005,'File preset operations changed fixed-window master amplitude: '+levels);return{windows,tolerance:.0005,apertureSeconds:2048/engine.ctx.sampleRate,scope:'Actual disconnected-speaker440Hz source into existing AudioEngine channel/master; equal fixed RMS windows, not sample-for-sample equality'};
  });
  await test('Disposed actual mixer rejects future file preset operations',async()=>{
   await mixer.dispose();let saveError,loadError;try{await mixer.saveVideoFX(0);}catch(e){saveError=e.message;}try{await mixer.load(0,A);}catch(e){loadError=e.message;}assert(/disposed/.test(saveError||'')&&/disposed/.test(loadError||''),'Disposed actual mixer accepted preset/file work');return{saveError,loadError};
  });
 }catch(error){checks.push({name:'Unhandled fixture/setup failure',passed:false,error:error.stack||error.message});}
 finally{await mixer?.dispose().catch(e=>notifications.push(e.message));try{osc?.stop();}catch{}osc?.disconnect();gain?.disconnect();engine.videoAnalyzers?.dispose();await engine.ctx.close();}
 report.passed=checks.filter(c=>c.passed).length;report.failed=checks.filter(c=>!c.passed).length;report.finishedAt=new Date().toISOString();$('#results').textContent=JSON.stringify(report,null,2);$('#status').textContent=`${report.passed}/${checks.length} actual per-file Video FX checks passed`;return report;
}
let running=false;$('#run').onclick=async()=>{if(running)return;running=true;$('#run').disabled=true;try{await runVideoFXPresetChecks();}finally{running=false;$('#run').disabled=false;}};
